import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

// `version` is raised on every save; an edit sends the version it loaded and is refused (409) when
// someone else has saved the person since.
// `statementCount` is how many statements were taken for them; `statedTotal` and `statementDate` are the last
// one's due-total and the sheet's today when it was taken (null with none).
export type Person = {
  id: number;
  name: string;
  grade: string;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
};

export const peopleQueryKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

export const peoplePath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/people`;

/** The sheet's people, in the order they were added. */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleQueryKey(sheet ?? ''),
    queryFn: () => getJson<Person[]>(peoplePath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** The id of the person whose editor is open (search param `editPerson`), or '' for none. */
export const useEditingPerson = () => useSearchParam('editPerson', asString);
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { GRADES, peoplePath, peopleQueryKey, usePeople, useEditingPerson, type Person } from './people';

// The person form: adds a person, or — while a person's editor is open — saves their changes. The
// editor remembers the version of the person it loaded; when someone else has saved them since, the
// save is refused and the form shows the person's current values (and version) instead.
function PersonForm() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [editing] = useEditingPerson();
  const people = usePeople();
  if (!user || !sheet) return null;
  const person = editing ? people.data?.find((p) => String(p.id) === editing) : undefined;
  // Keyed by who is being edited, so opening an editor fills the form with that person's values;
  // an editor for someone not on this sheet falls back to the add form.
  return <PersonFormFields key={`${sheet}:${person?.id ?? ''}`} sheet={sheet} person={person} />;
}

function PersonFormFields({ sheet, person }: { sheet: string; person?: Person }) {
  const [user] = useCurrentUser();
  const [, setEditing] = useEditingPerson();
  const [name, setName] = useState(person?.name ?? '');
  const [grade, setGrade] = useState(person?.grade ?? 'A');
  const [version, setVersion] = useState(person?.version);
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (body: { name: string; grade: string }) =>
      person
        ? putJson<Person>(`${peoplePath(sheet)}/${person.id}`, { ...body, version }, user)
        : postJson<Person>(peoplePath(sheet), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet) });
      if (person) {
        setEditing(undefined);
      } else {
        setName('');
        setGrade('A');
      }
    },
    onError: async (error) => {
      if (!person || !(error instanceof HttpError) || error.status !== 409) return;
      const current = await queryClient.fetchQuery({
        queryKey: peopleQueryKey(sheet),
        queryFn: () => getJson<Person[]>(peoplePath(sheet)),
        staleTime: 0,
      });
      const now = current.find((p) => p.id === person.id);
      if (now) {
        setName(now.name);
        setGrade(now.grade);
        setVersion(now.version);
      }
    },
  });
  const submit = useSubmitOnce(save);
  const conflict = save.error instanceof HttpError && save.error.status === 409;

  return (
    <form
      data-testid="person-form"
      onSubmit={(e) => {
        e.preventDefault();
        submit({ name, grade });
      }}
    >
      <h2>{person ? 'Edit person' : 'Add a person'}</h2>
      <input
        data-testid="person-form-name"
        placeholder="Name"
        value={name}
        onChange={(e) => { setName(e.target.value); save.reset(); }}
      />
      <select
        data-testid="person-form-grade"
        value={grade}
        onChange={(e) => { setGrade(e.target.value); save.reset(); }}
      >
        {GRADES.map((g) => (
          <option key={g} value={g}>{g}</option>
        ))}
      </select>
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {person ? 'Save' : 'Add person'}
      </button>
      {person && (
        <button type="button" data-testid="person-form-cancel" onClick={() => setEditing(undefined)}>
          Cancel
        </button>
      )}
      {save.isError && (
        <span data-testid="person-form-error">
          {conflict
            ? 'Someone else has saved this person since you opened the editor; the form now shows their current values.'
            : 'A name is required and must not already be in use on this sheet, and the grade must be A, B or C.'}
        </span>
      )}
    </form>
  );
}

export const contribution = HomeMain.fill({ order: 10, Component: PersonForm });
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { defineSlot } from '../Slot';

/** The home page's body: every panel on the one screen at `/` contributes itself here. */
export const HomeMain = defineSlot('home.main');
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx answer: its status tells a refusal (400) from a conflict with someone else's save (409).
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A change sends the signed-in name (`user`) as `X-User`, URI-encoded (a header is Latin-1 only),
// so the server records who made it.
const jsonHeaders = (user?: string): Record<string, string> =>
  user ? { 'Content-Type': 'application/json', 'X-User': encodeURIComponent(user) } : { 'Content-Type': 'application/json' };

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body?: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: jsonHeaders(user),
    body: body === undefined ? undefined : JSON.stringify(body),
  });
}
import { useRef } from 'react';
import type { UseMutationResult } from '@tanstack/react-query';

// Submits a mutation at most once at a time: a second submit (a double click) before the first has
// answered is dropped, so it stores one record, not two. `isPending` alone is not enough: it only
// disables the button once React has re-rendered, which a fast second click can beat.
export function useSubmitOnce<D, V, C>(mutation: UseMutationResult<D, Error, V, C>) {
  const busy = useRef(false);
  return (variables: V) => {
    if (busy.current) return;
    busy.current = true;
    mutation.reset();
    mutation.mutateAsync(variables).catch(() => undefined).finally(() => { busy.current = false; });
  };
}
